import { createProduct } from "./product";
import { withTax } from "./price";
import { stockNewProduct, takeStock } from "./inventory";
import { searchCatalog } from "./search";

export function findProduct(name: string, category: string) {
  const [first] = searchCatalog(name, category);
  return first ?? null;
}

export function listPrice(net: number, rate: number): number {
  return withTax({ net, taxClass: "standard" }, rate);
}

export function makeProduct(name: string, quantity: number) {
  return quantity > 0 ? stockNewProduct(name, quantity) : createProduct(name);
}

export function reserveProduct(productId: string, wanted: number) {
  return takeStock(productId, wanted);
}

import { createProduct } from "./product";

const byCategory = new Map<string, string[]>();

export function addToCategory(category: string, name: string) {
  const product = createProduct(name);
  byCategory.set(category, [...(byCategory.get(category) ?? []), product.id]);
  return product;
}

export function listCategory(category: string): string[] {
  return byCategory.get(category) ?? [];
}

import { createProduct } from "./product";
import { reserve } from "./stock";

const onHand = new Map<string, number>();

export function stockNewProduct(name: string, quantity: number) {
  const product = createProduct(name);
  onHand.set(product.id, quantity);
  return product;
}

export function takeStock(productId: string, wanted: number) {
  const result = reserve(onHand.get(productId) ?? 0, wanted);
  if (result.ok) onHand.set(productId, result.value);
  return result;
}

import { TAX_CLASSES } from "./product";
import { addMoney } from "../shared/money";

export interface Price {
  net: number;
  taxClass: (typeof TAX_CLASSES)[number];
}

export function withTax(price: Price, rate: number): number {
  const net = { cents: price.net, currency: "EUR" };
  const tax = { cents: Math.round(price.net * rate), currency: "EUR" };
  return addMoney(net, tax).cents;
}

import { newId } from "../shared/ids";
export type { Price } from "./price";

export const TAX_CLASSES = ["standard", "reduced", "zero"] as const;

export interface Product {
  id: string;
  name: string;
  taxClass: (typeof TAX_CLASSES)[number];
}

export function createProduct(name: string): Product {
  return { id: newId("prd"), name, taxClass: "standard" };
}

import { listCategory } from "./category";
import { expandTerms } from "./synonyms";

export function searchCatalog(term: string, category: string): string[] {
  const words = expandTerms(term);
  return listCategory(category).filter((id) => words.some((word) => id.includes(word)));
}

import { ok, fail } from "../shared/result";

export function reserve(onHand: number, wanted: number) {
  return wanted <= onHand ? ok(onHand - wanted) : fail<number>("not enough stock");
}

export const env = {
  nodeEnv: process.env.NODE_ENV ?? "development",
  currency: process.env.SHOP_CURRENCY ?? "EUR",
  mailFrom: process.env.SHOP_MAIL_FROM ?? "shop@manor.test",
};

import { env } from "./env";

export const flags = {
  giftWrap: env.nodeEnv !== "production",
  couponStacking: false,
};

export * from "./env";
export * from "./flags";
export * from "./limits";

import { flags } from "./flags";

export const limits = {
  maxCartLines: flags.couponStacking ? 50 : 25,
  freeShippingCents: 5000,
  maxChargeCents: 500000,
};

import { enqueue } from "./queue";
import { mayContact } from "./preferences";
import { env } from "../config/env";

export async function sendMail(to: string, subject: string, body: string): Promise<void> {
  if (!mayContact(to)) return;
  enqueue(`${env.mailFrom} > ${to}: ${subject}\n${body}`);
}

export async function sendInvoiceMail(to: string, orderId: string): Promise<void> {
  const invoice = await import("../payments/invoice");
  await sendMail(to, "Your invoice", invoice.renderInvoice(orderId));
}

import { requireEmail } from "../shared/validation";

const optedOut = new Set<string>();

export function optOut(email: string): void {
  if (requireEmail(email).ok) optedOut.add(email);
}

export function mayContact(email: string): boolean {
  return !optedOut.has(email);
}

import { logger } from "../shared/logger";

const pending: string[] = [];

export function enqueue(message: string): number {
  pending.push(message);
  logger.info(`queued ${pending.length}`);
  return pending.length;
}

import { renderTemplate } from "./templates";
import { sendMail } from "./mailer";
import { summarizeOrder } from "../orders/summary";
import { formatMoney } from "../shared/money";

export interface ReceiptInput {
  orderId: string;
  customerEmail: string;
  totalCents: number;
}

export async function sendReceipt(input: ReceiptInput): Promise<void> {
  const body = renderTemplate("receipt", { total: formatMoney(input.totalCents) });
  await sendMail(input.customerEmail, "Your receipt", body);
}

const templates: Record<string, string> = {
  receipt: "Thank you. Total: {total}",
  shipped: "Your parcel is on its way.",
};

export function renderTemplate(name: string, values: Record<string, string>): string {
  const text = templates[name] ?? "";
  return text.replace(/\{(\w+)\}/g, (_, key: string) => values[key] ?? "");
}

import { findProduct, listPrice } from "../catalog";
import { newId } from "../shared/ids";
import { limits } from "../config/limits";

export interface CartLine {
  productId: string;
  net: number;
}

const carts = new Map<string, CartLine[]>();

export function loadCart(cartId: string): CartLine[] {
  return carts.get(cartId) ?? [];
}

export function addLine(cartId: string, name: string, category: string, net: number): CartLine[] {
  const productId = findProduct(name, category) ?? newId("prd");
  const lines = loadCart(cartId);
  if (lines.length >= limits.maxCartLines) return lines;
  const next = [...lines, { productId, net: listPrice(net, 0.2) }];
  carts.set(cartId, next);
  return next;
}

export function clearCart(cartId: string): void {
  carts.delete(cartId);
}

// Checkout prices the cart, takes the payment and stores the order.
import { chargeCustomer } from "../payments/charge";
import { loadCart, clearCart } from "./cart";
import { computeTotals } from "./totals";
import { openOrder } from "./order";
import { saveOrder } from "./orderRepo";
import { logger } from "../shared/logger";

export function describeOrder(orderId: string): string {
  return `order ${orderId}`;
}

export async function checkout(cartId: string, email: string) {
  const lines = loadCart(cartId);
  const subtotal = lines.reduce((sum, line) => sum + line.net, 0);
  const totals = computeTotals(subtotal, lines.length, 0);
  const order = openOrder(cartId, subtotal, lines.length);
  await chargeCustomer(order.id, email, totals.totalCents);
  saveOrder(order);
  clearCart(cartId);
  logger.info(describeOrder(order.id));
  return order;
}

import { flags } from "../config/flags";

export function discountFor(lines: number, coupon: number): number {
  const stacked = flags.couponStacking ? coupon * 2 : coupon;
  return lines >= 10 ? stacked + 5 : stacked;
}

import { newId } from "../shared/ids";
import { canCancel } from "./status";
import { computeTotals } from "./totals";

export interface Order {
  id: string;
  cartId: string;
  status: "open" | "paid" | "shipped" | "cancelled";
  totalCents: number;
}

export function openOrder(cartId: string, subtotalCents: number, lines: number): Order {
  const totals = computeTotals(subtotalCents, lines, 0);
  return { id: newId("ord"), cartId, status: "open", totalCents: totals.totalCents };
}

export function cancelOrder(order: Order): Order {
  return canCancel(order.status) ? { ...order, status: "cancelled" } : order;
}

import { openOrder } from "./order";
import { logger } from "../shared/logger";

type StoredOrder = ReturnType<typeof openOrder>;

const stored = new Map<string, StoredOrder>();

export function saveOrder(order: StoredOrder): void {
  stored.set(order.id, order);
  logger.info(`stored ${order.id}`);
}

export function loadOrder(id: string): StoredOrder | null {
  return stored.get(id) ?? null;
}

import { limits } from "../config/limits";

export function shippingCents(subtotalCents: number): number {
  return subtotalCents >= limits.freeShippingCents ? 0 : 490;
}

export type OrderStatus = "open" | "paid" | "shipped" | "cancelled";

export function canCancel(status: OrderStatus): boolean {
  return status === "open" || status === "paid";
}

import { computeTotals } from "./totals";
import { formatMoney } from "../shared/money";
import { canCancel } from "./status";

export function summarizeOrder(subtotalCents: number, lines: number): string {
  const totals = computeTotals(subtotalCents, lines, 0);
  const note = canCancel("open") ? "can be cancelled" : "final";
  return `${lines} lines, ${formatMoney(totals.totalCents)}, ${note}`;
}

import { formatMoney, type Money } from "../shared/money";
import { discountFor } from "./discounts";
import { shippingCents } from "./shipping";

export interface Totals {
  subtotalCents: number;
  shippingCents: number;
  discountCents: number;
  totalCents: number;
  label: string;
}

export function computeTotals(subtotalCents: number, lines: number, coupon: number): Totals {
  const shipping = shippingCents(subtotalCents);
  const discount = discountFor(lines, coupon);
  const total = subtotalCents + shipping - discount;
  return {
    subtotalCents,
    shippingCents: shipping,
    discountCents: discount,
    totalCents: total,
    label: formatMoney(total),
  };
}

export function toMoney(totals: Totals, currency: string): Money {
  return { cents: totals.totalCents, currency };
}

import { sendReceipt } from "../notifications/receipt";
import { authorize } from "./gateway";
import { processingFee } from "./fees";
import { record } from "./ledger";
import { checkPayer } from "./methods";

export async function chargeCustomer(orderId: string, email: string, cents: number): Promise<boolean> {
  if (!checkPayer(email)) return false;
  const auth = authorize(orderId, cents + processingFee(cents));
  if (!auth.ok) return false;
  record(cents, `charge ${orderId}`);
  await sendReceipt({ orderId, customerEmail: email, totalCents: cents });
  return true;
}

import { limits } from "../config/limits";

export function processingFee(cents: number): number {
  const cap = Math.round(limits.maxChargeCents * 0.01);
  return Math.min(Math.round(cents * 0.015) + 25, cap);
}

import { env } from "../config/env";
import { ok, fail } from "../shared/result";

export function authorize(token: string, cents: number) {
  if (env.nodeEnv === "test") return ok(`test-${token}`);
  return cents > 0 ? ok(`auth-${token}-${cents}`) : fail<string>("nothing to charge");
}

import { balance } from "./ledger";
import { formatMoney } from "../shared/money";

export function renderInvoice(orderId: string): string {
  return `invoice ${orderId}: balance ${formatMoney(balance())}`;
}

import { newId } from "../shared/ids";
import { isoDate } from "../shared/dates";

export interface LedgerEntry {
  id: string;
  day: string;
  cents: number;
  memo: string;
}

const entries: LedgerEntry[] = [];

export function record(cents: number, memo: string): LedgerEntry {
  const entry = { id: newId("led"), day: isoDate(new Date()), cents, memo };
  entries.push(entry);
  return entry;
}

export function balance(): number {
  return entries.reduce((sum, entry) => sum + entry.cents, 0);
}

import { requireEmail } from "../shared/validation";

export function checkPayer(email: string): boolean {
  return requireEmail(email).ok;
}

import { authorize } from "./gateway";
import { record } from "./ledger";

export function refund(orderId: string, cents: number) {
  const auth = authorize(orderId, cents);
  if (auth.ok) record(-cents, `refund ${orderId}`);
  return auth;
}

export function isoDate(value: Date): string {
  return value.toISOString().slice(0, 10);
}

export function daysBetween(a: Date, b: Date): number {
  return Math.round((b.getTime() - a.getTime()) / 86400000);
}

import { nanoid } from "nanoid";

export function newId(prefix: string): string {
  return `${prefix}_${nanoid(10)}`;
}

import { env } from "../config";

export const logger = {
  info(message: string): void {
    if (env.nodeEnv !== "test") console.log(message);
  },
};

export interface Money {
  cents: number;
  currency: string;
}

export function formatMoney(cents: number): string {
  return (cents / 100).toFixed(2);
}

export function addMoney(a: Money, b: Money): Money {
  return { cents: a.cents + b.cents, currency: a.currency };
}

export type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function ok<T>(value: T): Result<T> {
  return { ok: true, value };
}

export function fail<T>(error: string): Result<T> {
  return { ok: false, error };
}

import { fail, ok } from "./result";
import { isoDate } from "./dates";

export function requireEmail(value: string) {
  return value.includes("@") ? ok(value) : fail<string>("not an email address");
}

export function requireFutureDate(value: Date, today: Date) {
  return value > today ? ok(isoDate(value)) : fail<string>("date is not in the future");
}
